import { Controller } from "@hotwired/stimulus";

/**
 * cremona-visual — plays the entrance animation of a Cremona visual template.
 *
 * Templates generated by tools/generate-stimulus.mjs carry:
 *   data-anim-order="N"      render order (used for the stagger cascade)
 *   data-anim-to="{...}"     the target style declarations (JSON)
 *   data-anim-initial="..."  the initial inline style (CSS text), restored before a replay
 * and keep their initial hidden style inline.
 *
 * On connect (or when the element enters the viewport, depending on the
 * `trigger` value) each animated element is transitioned to its target with a
 * stagger derived from its order. Replays when re-entering the viewport when
 * `trigger` is `inViewRepeat`. With `prefers-reduced-motion: reduce` the end
 * state is applied without transitions.
 *
 * Targets: the element with data-controller itself.
 * Values:
 *   trigger: "mount" | "inView" | "inViewRepeat" (default "inViewRepeat")
 *   duration: base transition duration in ms (default 450)
 *   stagger: per-order delay in ms (default 70, capped)
 *   delay: base delay in ms (default 60)
 */
export default class CremonaVisualController extends Controller {
  static values = {
    trigger: { type: String, default: "inViewRepeat" },
    duration: { type: Number, default: 450 },
    stagger: { type: Number, default: 70 },
    delay: { type: Number, default: 60 },
  };

  connect() {
    this.animated = Array.from(this.element.querySelectorAll("[data-anim-to]"));
    if (this.element.hasAttribute("data-anim-to")) this.animated.unshift(this.element);
    if (this.animated.length === 0) return;

    if (this.triggerValue === "mount") {
      this.play();
      return;
    }
    this.observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            this.play();
            if (this.triggerValue === "inView") this.observer.disconnect();
          } else if (this.triggerValue === "inViewRepeat") {
            this.reset();
          }
        }
      },
      { threshold: 0.5 },
    );
    this.observer.observe(this.element);
  }

  disconnect() {
    this.observer?.disconnect();
  }

  play() {
    if (this.played && this.triggerValue === "inView") return;
    this.played = true;
    const still = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    const targets = this.animated.map((el) => {
      const order = Number(el.getAttribute("data-anim-order") || 0);
      const to = parseTarget(el.getAttribute("data-anim-to"));
      const d = this.delayValue + Math.min(order, 14) * this.staggerValue;
      el.style.transition = still
        ? "none"
        : `opacity ${this.durationValue}ms ease-out ${d}ms${
            to.transform ? `, transform ${this.durationValue}ms ease-out ${d}ms` : ""
          }`;
      return [el, to];
    });
    // Commit the hidden state first: a play right after connect (trigger "mount",
    // markup inserted by Turbo) would otherwise jump straight to the end state.
    void this.element.offsetWidth;
    for (const [el, to] of targets) {
      for (const [prop, value] of Object.entries(to)) el.style.setProperty(prop, value);
    }
  }

  reset() {
    this.played = false;
    for (const el of this.animated) {
      el.style.transition = "none";
      const initial = parseDeclarations(el.getAttribute("data-anim-initial"));
      for (const prop of Object.keys(parseTarget(el.getAttribute("data-anim-to")))) {
        if (prop in initial) el.style.setProperty(prop, initial[prop]);
      }
    }
  }
}

/** `data-anim-to`: the target declarations, as JSON. */
function parseTarget(json) {
  if (!json) return {};
  try {
    return JSON.parse(json);
  } catch {
    return {};
  }
}

/** `data-anim-initial`: the initial inline style, as CSS text ("opacity:0;transform:…"). */
function parseDeclarations(css) {
  const out = {};
  for (const declaration of (css ?? "").split(";")) {
    const colon = declaration.indexOf(":");
    if (colon > 0) out[declaration.slice(0, colon).trim()] = declaration.slice(colon + 1).trim();
  }
  return out;
}
